#!/usr/bin/env node
// #547: freeze an already-built candidate; never rebuild or modify the formal public directory.
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
export function freezePreview(source, output){
 const root=resolve(source), manifestBytes=readFileSync(join(root,'version.json'));
 const manifest=JSON.parse(manifestBytes);
 if(manifest.v!==1||manifest.algo!=='sha256'||manifest.preview?.channel!=='preview')throw Error('candidate must have a preview manifest');
 const paths=Object.keys(manifest.files).sort();
 if(sha(paths.map(path=>`${manifest.files[path]}  ${path}\n`).join(''))!==manifest.combined)throw Error('candidate combined hash mismatch');
 const files={};
 for(const path of [...paths,'version.json','version.js']){
  if(path.startsWith('/')||path.includes('\\')||path.includes('%')||path.split('/').some(x=>!x||x==='.'||x==='..'||x==='.preview'))throw Error('invalid candidate path');
  const bytes=readFileSync(join(root,path));
  if(path!=='version.json'&&path!=='version.js'&&sha(bytes)!==manifest.files[path])throw Error('candidate file mismatch: '+path);
  files[path]=bytes.toString('base64');
 }
 if(readFileSync(join(root,'version.js'),'utf8')!=='// generated by build.mjs — do not edit\nexport default '+manifestBytes.toString().trimEnd()+';\n')throw Error('candidate version module differs');
 const bundle=Buffer.from(JSON.stringify({v:1,manifest,files}));
 if(bundle.length>24*1024*1024)throw Error('candidate bundle exceeds asset limit');
 const hash=sha(bundle);mkdirSync(output,{recursive:true});writeFileSync(join(output,hash+'.json'),bundle);
 return {bundleSha256:hash,manifestSha256:sha(manifestBytes),combined:manifest.combined,bytes:bundle.length,files:paths.length+2};
}
if(process.argv[1]===fileURLToPath(import.meta.url)){
 if(process.argv.length!==4)throw Error('usage: node preview-bundle.mjs <built-candidate-public> <formal-public/.preview>');
 console.log(JSON.stringify(freezePreview(process.argv[2],process.argv[3]),null,2));
}
